const input = $input.first();
const body = input.json.body ?? input.json;
const document = input.binary?.document;

if (!document) {
  return [{ json: { automationFailed: true, failureReason: 'The validated document was not received.' } }];
}

const required = ['submissionId', 'companyName', 'website', 'contactName', 'contactEmail', 'serviceRequested', 'desiredStartDate'];
const missing = required.filter((field) => !String(body[field] ?? '').trim());
if (missing.length) {
  return [{ json: { automationFailed: true, failureReason: `Missing validated fields: ${missing.join(', ')}` } }];
}

return [{
  json: {
    submissionId: String(body.submissionId).trim(),
    submittedAt: new Date().toISOString(),
    companyName: String(body.companyName).trim(),
    website: String(body.website).trim(),
    contactName: String(body.contactName).trim(),
    contactEmail: String(body.contactEmail).trim().toLowerCase(),
    serviceRequested: String(body.serviceRequested).trim(),
    desiredStartDate: String(body.desiredStartDate).trim(),
    notes: String(body.notes ?? '').trim(),
    documentName: document.fileName ?? 'client-brief',
    documentMimeType: document.mimeType ?? 'application/octet-stream'
  },
  binary: input.binary
}];

const ai = $input.first().json;
const intake = $('Normalise Validated Intake').item.json;

if (ai.error) {
  return [{ json: { automationFailed: true, failureReason: 'The AI document review could not be completed.' } }];
}

const text = ai.content?.parts?.map((part) => part.text ?? '').join('')
  ?? ai.candidates?.[0]?.content?.parts?.map((part) => part.text ?? '').join('')
  ?? ai.text
  ?? '';

let parsed;
try {
  parsed = JSON.parse(String(text).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim());
} catch (error) {
  return [{ json: { automationFailed: true, failureReason: 'The AI returned an invalid structured review.' } }];
}

const fields = parsed.extractedFields && typeof parsed.extractedFields === 'object' ? parsed.extractedFields : {};
const requiredFields = ['companyName', 'contactName', 'contactEmail', 'serviceRequested', 'budget', 'targetLaunchDate', 'projectSummary', 'dependencies'];
const missingFields = requiredFields.filter((field) => !String(fields[field] ?? '').trim());
const conflicts = Array.isArray(parsed.conflicts) ? parsed.conflicts.filter(Boolean).map(String) : [];
const quality = String(parsed.documentQuality ?? 'UNREADABLE').toUpperCase();

let reviewStatus = 'COMPLETE';
if (quality === 'UNREADABLE' || conflicts.length) {
  reviewStatus = 'MANUAL_REVIEW';
} else if (missingFields.length) {
  reviewStatus = 'MISSING_INFORMATION';
}

const fallbackReason = reviewStatus === 'COMPLETE'
  ? 'The brief contains every required onboarding field and no material conflicts were detected.'
  : reviewStatus === 'MISSING_INFORMATION'
    ? `The brief is missing: ${missingFields.join(', ')}.`
    : conflicts.length
      ? `Manual review is required because: ${conflicts.join('; ')}.`
      : 'Manual review is required because the document could not be read reliably.';

let followUpDraft = '';
if (reviewStatus === 'MISSING_INFORMATION') {
  followUpDraft = String(parsed.followUpDraft ?? '').trim() || `Hi ${intake.contactName}, thanks for sending the brief for ${intake.companyName}. Before we begin, could you please confirm: ${missingFields.join(', ')}? Once we have those details, we can complete the onboarding review.`;
}

return [{ json: {
  automationFailed: false,
  submissionId: intake.submissionId,
  reviewStatus,
  extractedFields: Object.fromEntries(requiredFields.map((field) => [field, String(fields[field] ?? '').trim()])),
  missingFields,
  reviewReason: String(parsed.reviewReason ?? '').trim() || fallbackReason,
  followUpDraft,
  conflicts,
  approvalStatus: 'PENDING'
} }];
